import unittest

from build_order import build_order, CycleError


def is_valid_topo(order, deps):
    """Every dependency must appear before the node that depends on it,
    and every node (keys + dep-only) must appear exactly once."""
    nodes = set(deps)
    for d in deps:
        nodes.update(deps[d])
    if sorted(order) != sorted(nodes):
        return False
    if len(order) != len(set(order)):
        return False
    pos = {n: i for i, n in enumerate(order)}
    for node, dlist in deps.items():
        for dep in dlist:
            if pos[dep] >= pos[node]:
                return False
    return True


class TestBuildOrder(unittest.TestCase):
    def test_linear_chain(self):
        deps = {"a": ["b"], "b": ["c"], "c": []}
        order = build_order(deps)
        self.assertTrue(is_valid_topo(order, deps))
        self.assertEqual(order, ["c", "b", "a"])

    def test_diamond(self):
        deps = {"d": ["b", "c"], "b": ["a"], "c": ["a"], "a": []}
        order = build_order(deps)
        self.assertTrue(is_valid_topo(order, deps))
        self.assertEqual(order[0], "a")
        self.assertEqual(order[-1], "d")
        self.assertEqual(order, ["a", "b", "c", "d"])

    def test_alphabetical_tiebreak_roots(self):
        deps = {"c": [], "a": [], "b": []}
        order = build_order(deps)
        self.assertEqual(order, ["a", "b", "c"])

    def test_dependency_only_node_included(self):
        # "z" never appears as a key, only as a dependency.
        deps = {"a": ["z"]}
        order = build_order(deps)
        self.assertTrue(is_valid_topo(order, deps))
        self.assertEqual(order, ["z", "a"])

    def test_single_node(self):
        deps = {"a": []}
        self.assertEqual(build_order(deps), ["a"])

    def test_empty(self):
        self.assertEqual(build_order({}), [])

    def test_two_node_cycle(self):
        with self.assertRaises(CycleError):
            build_order({"a": ["b"], "b": ["a"]})

    def test_self_loop(self):
        with self.assertRaises(CycleError):
            build_order({"a": ["a"]})

    def test_longer_cycle(self):
        with self.assertRaises(CycleError):
            build_order({"a": ["b"], "b": ["c"], "c": ["a"]})

    def test_duplicate_dependency(self):
        deps = {"a": ["b", "b"], "b": []}
        order = build_order(deps)
        self.assertEqual(order, ["b", "a"])
        self.assertEqual(len(order), len(set(order)))

    def test_full_tiebreak_with_structure(self):
        # roots g, f independent; both feed nothing else. e depends on f, g.
        deps = {"e": ["f", "g"], "f": [], "g": []}
        order = build_order(deps)
        self.assertTrue(is_valid_topo(order, deps))
        self.assertEqual(order, ["f", "g", "e"])


if __name__ == "__main__":
    unittest.main(verbosity=2)

