"""Short demo of call_with_retry against a fake flaky function."""

import time

from resilient_client import TransientError, call_with_retry


def make_flaky(fail_times):
    """Return a zero-arg fn that raises TransientError `fail_times` times,
    then returns a success value. Counts its own attempts."""
    state = {"attempts": 0}

    def fn():
        state["attempts"] += 1
        if state["attempts"] <= fail_times:
            raise TransientError(f"overloaded (attempt {state['attempts']})")
        return f"ok after {state['attempts']} attempt(s)"

    return fn, state


def main():
    delays = []

    def sleep(seconds):
        delays.append(seconds)  # record instead of really sleeping for the demo

    fn, state = make_flaky(fail_times=2)
    result = call_with_retry(
        fn,
        max_attempts=5,
        base=1.0,
        factor=2.0,
        sleep=sleep,
    )

    print(f"result : {result}")
    print(f"attempts: {state['attempts']}")
    print(f"delays  : {delays}")


if __name__ == "__main__":
    main()

