"""Deterministic unittest suite for call_with_retry.

A recording fake `sleep` captures delays without ever sleeping; `rng` is a
fixed deterministic callable. No real time passes.
"""

import unittest

from resilient_client import PermanentError, TransientError, call_with_retry


class RecordingSleep:
    """Fake sleep that records each delay and never blocks."""

    def __init__(self):
        self.delays = []

    def __call__(self, seconds):
        self.delays.append(seconds)


def const_rng(value):
    """Return a zero-arg callable that always yields `value`."""
    return lambda: value


def make_fn(behaviors):
    """Build a zero-arg fn driven by a list of behaviors.

    Each behavior is either an Exception instance (raised) or a ('return', val)
    tuple (returned). Records how many times it was called in `.calls`.
    """
    state = {"calls": 0}

    def fn():
        idx = state["calls"]
        state["calls"] += 1
        b = behaviors[idx]
        if isinstance(b, BaseException):
            raise b
        return b[1]

    fn.state = state
    return fn


class TestCallWithRetry(unittest.TestCase):
    def test_success_first_try(self):
        sleep = RecordingSleep()
        fn = make_fn([("return", 42)])
        result = call_with_retry(fn, sleep=sleep)
        self.assertEqual(result, 42)
        self.assertEqual(fn.state["calls"], 1)
        self.assertEqual(sleep.delays, [])

    def test_success_after_k_transient_failures(self):
        sleep = RecordingSleep()
        fn = make_fn([TransientError("a"), TransientError("b"), ("return", "ok")])
        result = call_with_retry(
            fn, max_attempts=5, base=1.0, factor=2.0, sleep=sleep
        )
        self.assertEqual(result, "ok")
        self.assertEqual(fn.state["calls"], 3)
        self.assertEqual(sleep.delays, [1.0, 2.0])

    def test_permanent_raised_immediately(self):
        sleep = RecordingSleep()
        fn = make_fn([PermanentError("nope"), ("return", "unreached")])
        with self.assertRaises(PermanentError):
            call_with_retry(fn, sleep=sleep)
        self.assertEqual(fn.state["calls"], 1)
        self.assertEqual(sleep.delays, [])

    def test_unknown_exception_propagates_immediately(self):
        sleep = RecordingSleep()
        fn = make_fn([ValueError("boom"), ("return", "unreached")])
        with self.assertRaises(ValueError):
            call_with_retry(fn, sleep=sleep)
        self.assertEqual(fn.state["calls"], 1)
        self.assertEqual(sleep.delays, [])

    def test_exhaustion_raises_last_transient(self):
        sleep = RecordingSleep()
        last = TransientError("last")
        fn = make_fn([TransientError("first"), TransientError("mid"), last])
        with self.assertRaises(TransientError) as ctx:
            call_with_retry(
                fn, max_attempts=3, base=1.0, factor=2.0, sleep=sleep
            )
        self.assertIs(ctx.exception, last)
        self.assertEqual(fn.state["calls"], 3)
        self.assertEqual(sleep.delays, [1.0, 2.0])

    def test_exponential_backoff_sequence(self):
        sleep = RecordingSleep()
        fn = make_fn(
            [TransientError(), TransientError(), TransientError(), ("return", 1)]
        )
        call_with_retry(
            fn, max_attempts=5, base=1.0, factor=2.0, sleep=sleep
        )
        self.assertEqual(sleep.delays, [1.0, 2.0, 4.0])

    def test_max_delay_cap(self):
        sleep = RecordingSleep()
        fn = make_fn([TransientError(), TransientError(), ("return", 1)])
        call_with_retry(
            fn, max_attempts=5, base=10.0, factor=10.0, max_delay=60.0, sleep=sleep
        )
        # base_delay = [min(60, 10), min(60, 100)] = [10, 60]
        self.assertEqual(sleep.delays, [10.0, 60.0])

    def test_retry_after_honored(self):
        sleep = RecordingSleep()
        fn = make_fn(
            [TransientError("rl", retry_after=7.5), ("return", "ok")]
        )
        call_with_retry(
            fn, max_attempts=5, base=1.0, factor=2.0, jitter=0.5,
            rng=const_rng(0.99), sleep=sleep,
        )
        # retry_after overrides backoff AND jitter
        self.assertEqual(sleep.delays, [7.5])

    def test_retry_after_capped_by_max_delay(self):
        sleep = RecordingSleep()
        fn = make_fn(
            [TransientError("rl", retry_after=1000.0), ("return", "ok")]
        )
        call_with_retry(
            fn, max_attempts=5, max_delay=60.0, sleep=sleep
        )
        self.assertEqual(sleep.delays, [60.0])

    def test_jitter_formula_exact(self):
        sleep = RecordingSleep()
        fn = make_fn([TransientError(), ("return", "ok")])
        call_with_retry(
            fn, max_attempts=5, base=1.0, factor=2.0, jitter=0.5,
            rng=const_rng(0.4), sleep=sleep,
        )
        # base_delay=1.0 ; delay = 1.0 * (1 - 0.5 + 0.5*0.4) = 0.7
        self.assertEqual(len(sleep.delays), 1)
        self.assertAlmostEqual(sleep.delays[0], 0.7)

    def test_jitter_across_multiple_attempts(self):
        sleep = RecordingSleep()
        fn = make_fn([TransientError(), TransientError(), ("return", "ok")])
        call_with_retry(
            fn, max_attempts=5, base=1.0, factor=2.0, jitter=1.0,
            rng=const_rng(0.5), sleep=sleep,
        )
        # jitter=1.0: delay = base_delay * (0 + 1*0.5) = base_delay * 0.5
        # base_delays = [1.0, 2.0] -> [0.5, 1.0]
        self.assertEqual(len(sleep.delays), 2)
        self.assertAlmostEqual(sleep.delays[0], 0.5)
        self.assertAlmostEqual(sleep.delays[1], 1.0)

    def test_no_rng_needed_when_jitter_zero(self):
        sleep = RecordingSleep()
        fn = make_fn([TransientError(), ("return", "ok")])
        # rng left as None; jitter defaults to 0 -> must not be called
        result = call_with_retry(fn, base=1.0, factor=2.0, sleep=sleep)
        self.assertEqual(result, "ok")
        self.assertEqual(sleep.delays, [1.0])


if __name__ == "__main__":
    unittest.main(verbosity=2)

