import unittest

from sse_parser import parse_sse, assemble_text


class TestParseSSE(unittest.TestCase):
    def test_single_event_single_chunk(self):
        self.assertEqual(
            parse_sse(['data: {"delta": "Hi"}\n\n']),
            [{"delta": "Hi"}],
        )

    def test_multiple_events_one_chunk(self):
        self.assertEqual(
            parse_sse(['data: {"a": 1}\n\ndata: {"a": 2}\n\n']),
            [{"a": 1}, {"a": 2}],
        )

    def test_event_split_mid_json(self):
        self.assertEqual(
            parse_sse(['data: {"del', 'ta": "Hi"}\n\n']),
            [{"delta": "Hi"}],
        )

    def test_event_split_mid_line_and_across_three_chunks(self):
        # boundary splits the "data:" field name itself, and event spans 3 chunks
        self.assertEqual(
            parse_sse(['da', 'ta: {"delta": ', '"yo"}\n\n']),
            [{"delta": "yo"}],
        )

    def test_done_terminates_and_ignores_after(self):
        self.assertEqual(
            parse_sse([
                'data: {"delta": "a"}\n\n',
                'data: [DONE]\n\n',
                'data: {"delta": "b"}\n\n',
            ]),
            [{"delta": "a"}],
        )

    def test_comment_and_other_fields_ignored(self):
        self.assertEqual(
            parse_sse([': ping\n\nevent: message\ndata: {"delta": "x"}\nid: 7\n\n']),
            [{"delta": "x"}],
        )

    def test_malformed_json_skipped_valid_kept(self):
        self.assertEqual(
            parse_sse(['data: not json\n\ndata: {"delta": "ok"}\n\n']),
            [{"delta": "ok"}],
        )

    def test_leading_space_with_and_without(self):
        with_space = parse_sse(['data: {"v": 1}\n\n'])
        without_space = parse_sse(['data:{"v": 1}\n\n'])
        self.assertEqual(with_space, [{"v": 1}])
        self.assertEqual(without_space, [{"v": 1}])
        self.assertEqual(with_space, without_space)

    def test_empty_input(self):
        self.assertEqual(parse_sse([]), [])

    def test_trailing_event_without_blank_line_flushed(self):
        # final event not terminated by a blank line is still emitted
        self.assertEqual(
            parse_sse(['data: {"delta": "tail"}']),
            [{"delta": "tail"}],
        )


