class ExpiringCache:
 def __init__(self,clock): self.clock=clock; self.data={}
 def set(self,key,value,ttl): self.data[key]=(value,self.clock()+ttl)
 def get(self,key):
  value,expiry=self.data[key]
  if self.clock()>expiry: raise KeyError(key)
  return value
 def delete(self,key): return self.data.pop(key,None) is not None
 def __len__(self): return len(self.data)

